import sys
from collections import defaultdict
from fractions import Fraction

def solve(N, M, paths):
    graph = defaultdict(list)
    degree = [0] * N

    for K, L in paths:
        graph[K].append(L)
        graph[L].append(K)
        degree[K] += 1
        degree[L] += 1

    def dp(node):
        if node == N - 1:
            return {0}
        if len(graph[node]) == 1:
            prev_node = graph[node][0]
            return {dp(prev_node)[0] + 2}

        sum_of_expected_values = 0
        num_neighbors = len(graph[node])
        for neighbor in graph[node]:
            if neighbor != prev_node:
                sum_of_expected_values += sum(dp(neighbor))

        expected_value = sum_of_expected_values / (num_neighbors - 1) + 1
        memo[node] = expected_value

        return {expected_value}

    memo = {}
    result = sum(dp(0)) / degree[0]
    return float(result)

