import sys
from fractions import Fraction

def calculate_expected_time(N, M, paths):
    # Create adjacency list
    adj_list = [[] for _ in range(N)]
    for K, L in paths:
        adj_list[K].append(L)
        adj_list[L].append(K)

    # Initialize dp table
    dp = [Fraction(0) for _ in range(N)]
    visited = [False] * N

    def dfs(node, parent):
        if visited[node]:
            return Fraction(0)

        visited[node] = True
        children_count = 0
        for neighbor in adj_list[node]:
            if neighbor != parent:
                children_count += 1

        if node == N - 1:
            dp[node] = Fraction(1)
        else:
            for neighbor in adj_list[node]:
                if neighbor != parent:
                    dp[node] += dfs(neighbor, node) / children_count + Fraction(1)

        visited[node] = False
        return dp[node]

    dfs(0, None)

    return float(dp[0])

